use std::fs;
use std::path::Path;

use tansu2::api_types::*;
use ts_rs::TS;

fn main() {
    let check = std::env::args().any(|arg| arg == "--check");
    let mut output = String::from(
        "// Generated by cargo run --bin gen-api-types. Do not edit.\n/* oxlint-disable typescript-eslint/array-type */\n\n",
    );
    push::<VaultEntry>(&mut output);
    push::<NoteMeta>(&mut output);
    push::<NoteDocument>(&mut output);
    push::<RevisionMeta>(&mut output);
    push::<RevisionDocument>(&mut output);
    push::<NoteEventKind>(&mut output);
    push::<NoteEventSource>(&mut output);
    push::<ConflictDraftMeta>(&mut output);
    push::<ConflictDraftDocument>(&mut output);
    push::<Settings>(&mut output);
    push::<AppVaultSettings>(&mut output);
    push::<AppAuthSettings>(&mut output);
    push::<AppSettings>(&mut output);
    push::<V2AppSettingsResponse>(&mut output);
    push::<SearchStatus>(&mut output);
    push::<SearchFieldScores>(&mut output);
    push::<SearchHit>(&mut output);
    push::<ServerEvent>(&mut output);
    push::<ServerEventKind>(&mut output);
    push::<CreateNoteRequest>(&mut output);
    push::<SaveNoteRequest>(&mut output);
    push::<SaveNoteDeltaRequest>(&mut output);
    push::<TextEdit>(&mut output);
    push::<TextPosition>(&mut output);
    push::<RenameNoteRequest>(&mut output);
    push::<NoteMutationResponse>(&mut output);
    push::<ImageUploadResponse>(&mut output);
    push::<ApiErrorResponse>(&mut output);
    push::<ApiErrorKind>(&mut output);
    push::<PathValidationReason>(&mut output);
    push::<UnresolvedReason>(&mut output);
    push::<V2VaultMeta>(&mut output);
    push::<V2BootstrapResponse>(&mut output);
    push::<V2VaultBootstrapResponse>(&mut output);
    push::<V2NoteMeta>(&mut output);
    push::<V2NoteDocument>(&mut output);
    push::<V2NotePrecondition>(&mut output);
    push::<V2CreateNoteRequest>(&mut output);
    push::<V2SaveNoteRequest>(&mut output);
    push::<V2SaveNoteDeltaRequest>(&mut output);
    push::<V2RenameNoteRequest>(&mut output);
    push::<V2DeleteNoteRequest>(&mut output);
    push::<V2RestoreRevisionRequest>(&mut output);
    push::<V2RestoreConflictRequest>(&mut output);
    push::<V2ConflictDraftMeta>(&mut output);
    push::<V2ConflictDraftDocument>(&mut output);
    push::<V2RevisionMeta>(&mut output);
    push::<V2RevisionDocument>(&mut output);
    push::<V2SettingsRequest>(&mut output);
    push::<V2SettingsResponse>(&mut output);
    push::<V2ImageUploadResponse>(&mut output);
    push::<V2MutationOutcome>(&mut output);
    push::<V2MutationResponse>(&mut output);
    push::<V2SearchMode>(&mut output);
    push::<V2SearchOverlay>(&mut output);
    push::<V2SearchRequest>(&mut output);
    push::<V2ExcerptRange>(&mut output);
    push::<V2SourceRange>(&mut output);
    push::<V2SearchHitIdentity>(&mut output);
    push::<V2SearchHit>(&mut output);
    push::<V2OverlayCoverage>(&mut output);
    push::<V2SearchResponse>(&mut output);
    push::<V2QuickOpenRequest>(&mut output);
    push::<V2QuickOpenHit>(&mut output);
    push::<V2QuickOpenResponse>(&mut output);
    push::<V2ServerEventUpdate>(&mut output);
    push::<V2ServerEvent>(&mut output);
    push::<V2ApiErrorResponse>(&mut output);
    push::<V2ApiErrorKind>(&mut output);

    let path = Path::new("web/ts/types.generated.ts");
    if check {
        let current = fs::read_to_string(path).unwrap_or_default();
        if current != output {
            eprintln!("generated API types are stale");
            std::process::exit(1);
        }
    } else {
        fs::create_dir_all(path.parent().expect("generated type parent")).unwrap();
        fs::write(path, output).unwrap();
    }
}

fn push<T: TS>(output: &mut String) {
    let decl = T::decl(&ts_rs::Config::default());
    output.push_str(&decl.replacen("type ", "export type ", 1));
    output.push_str("\n\n");
}
